quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");
const id = lines[0];
const newText = lines[1];
const tree = JSON.parse(lines.slice(2).join("\n"));

// 深さ優先(親 → 子を前から順)で、最初に見つかった id の要素を返す。なければ null
function findById(node, id) {
  if (node.id === id) return node;
  for (const child of node.children || []) {
    const found = findById(child, id);
    if (found !== null) return found;
  }
  return null;
}

const target = findById(tree, id);
if (target === null) {
  console.log("not found");
} else {
  target.children = [{ text: newText }];
  console.log(JSON.stringify(tree));
}

